UPDATE a1_speaking_units SET level='A1', script_json=json_object('unitTitle',title,'level','A1','objective_es','Practicar inglés en situaciones relacionadas con ' || title || '.','steps',json_array(json_object('id',1,'tutorLine','Hello! What is your name?' || title || ' What do you know about it?','tutorAudio','Hello! What is your name?' || title || ' What do you know about it?','expectedResponse','My name is [name].','instruction_es','Saluda y di tu nombre en inglés.','evaluationCriteria','Acepta ''My name is X'', ''I''m X'', ''I am X'' o solo el nombre.','sampleAnswers',json_array('My name is Maria','I''m John','Carlos')),json_object('id',2,'tutorLine','Nice to meet you. Where are you from?','tutorAudio','Nice to meet you. Where are you from?','expectedResponse','I''m from [place].','instruction_es','Di de dónde eres.','evaluationCriteria','Acepta ''I''m from X'', ''I come from X'' o solo el lugar.','sampleAnswers',json_array('I''m from Spain','I come from Madrid','Spain')),json_object('id',3,'tutorLine','What do you like about this topic?','tutorAudio','What do you like about this topic?','expectedResponse','I like [thing].','instruction_es','Di algo que te guste relacionado con la unidad.','evaluationCriteria','Acepta una preferencia comprensible relacionada con el tema.','sampleAnswers',json_array('I like it','I like the food','It''s interesting')),json_object('id',4,'tutorLine','What do you usually do?','tutorAudio','What do you usually do?','expectedResponse','I usually [action].','instruction_es','Describe una acción habitual con una frase sencilla.','evaluationCriteria','Acepta una rutina o acción en presente simple.','sampleAnswers',json_array('I usually go by bus','I work every day','I practise English')),json_object('id',5,'tutorLine','Great! What would you like to do next?','tutorAudio','Great! What would you like to do next?','expectedResponse','I''d like to [action].','instruction_es','Explica qué quieres hacer a continuación.','evaluationCriteria','Acepta una despedida o intención sencilla y pertinente.','sampleAnswers',json_array('I''d like to go now','Thank you, goodbye','I want to practise more')))) WHERE unit_number=1;
