UPDATE a1_speaking_units SET level='B1', script_json=json_object('unitTitle',title,'level','B1','objective_es','Practicar inglés en situaciones relacionadas con ' || title || '.','steps',json_array(json_object('id',1,'tutorLine','Describe an experience related to ' || title || ' What do you know about it?','tutorAudio','Describe an experience related to ' || title || ' What do you know about it?','expectedResponse','I once [experience].','instruction_es','Describe una experiencia relacionada con el tema.','evaluationCriteria','Acepta una experiencia narrada con tiempos pasados.','sampleAnswers',json_array('I once travelled alone','I have tried this before')),json_object('id',2,'tutorLine','What had you expected before it happened?','tutorAudio','What had you expected before it happened?','expectedResponse','I had expected [expectation].','instruction_es','Explica qué habías esperado antes de la experiencia.','evaluationCriteria','Acepta una expectativa comprensible, preferiblemente con past perfect.','sampleAnswers',json_array('I had expected it to be easier','I thought it would be simple')),json_object('id',3,'tutorLine','How did you deal with the main challenge?','tutorAudio','How did you deal with the main challenge?','expectedResponse','I managed to [solution].','instruction_es','Explica cómo resolviste la principal dificultad.','evaluationCriteria','Acepta una solución y una explicación coherente.','sampleAnswers',json_array('I asked someone for help','I managed to solve it')),json_object('id',4,'tutorLine','How has that experience changed your approach?','tutorAudio','How has that experience changed your approach?','expectedResponse','It has taught me to [lesson].','instruction_es','Explica qué has aprendido de esa experiencia.','evaluationCriteria','Acepta una reflexión con present perfect o equivalente.','sampleAnswers',json_array('It has taught me to plan ahead','I have become more careful')),json_object('id',5,'tutorLine','What advice would you give someon